USE futurefinance;
CREATE OR REPLACE VIEW monthly_financial_summary AS SELECT u.id user_id,DATE_FORMAT(i.received_on,'%Y-%m') month,SUM(i.amount) monthly_income,COALESCE((SELECT SUM(e.amount) FROM expenses e WHERE e.user_id=u.id AND DATE_FORMAT(e.spent_on,'%Y-%m')=DATE_FORMAT(i.received_on,'%Y-%m')),0) monthly_expenses FROM users u JOIN income i ON i.user_id=u.id GROUP BY u.id,DATE_FORMAT(i.received_on,'%Y-%m');
CREATE OR REPLACE VIEW investment_portfolio_summary AS SELECT user_id,investment_type,SUM(current_value) portfolio_value,SUM(current_value)/SUM(SUM(current_value)) OVER(PARTITION BY user_id)*100 allocation_pct FROM investments GROUP BY user_id,investment_type;
CREATE OR REPLACE VIEW goal_progress_summary AS SELECT id,user_id,name,target_amount,current_amount,ROUND(current_amount/target_amount*100,2) progress_pct, GREATEST(0,target_amount-current_amount) remaining FROM financial_goals;
CREATE OR REPLACE VIEW expense_category_summary AS SELECT user_id,DATE_FORMAT(spent_on,'%Y-%m') month,category,SUM(amount) amount FROM expenses GROUP BY user_id,month,category;
CREATE OR REPLACE VIEW financial_health_summary AS SELECT p.user_id,p.savings,p.monthly_income,COALESCE(e.expenses,0) expenses,ROUND((p.monthly_income-COALESCE(e.expenses,0))/NULLIF(p.monthly_income,0)*100,2) savings_rate FROM financial_profiles p LEFT JOIN (SELECT user_id,SUM(amount) expenses FROM expenses WHERE spent_on>=DATE_FORMAT(CURDATE(),'%Y-%m-01') GROUP BY user_id)e ON e.user_id=p.user_id;
